TRANSITIONS = {
    ('new', 'pay'): 'paid',
    ('paid', 'ship'): 'shipped',
    ('shipped', 'deliver'): 'delivered',
    ('delivered', 'return'): 'returned',
}

def advance(status, action):
    if status in ('returned', 'cancelled'):
        return status, f'{status} is terminal'
    key = (status, action)
    if key not in TRANSITIONS:
        return status, f'illegal action {action!r} on {status}'
    return TRANSITIONS[key], 'ok'

for status, action in (('new', 'pay'), ('paid', 'deliver'), ('delivered', 'return'), ('returned', 'pay')):
    next_status, note = advance(status, action)
    print(f'{status:10} + {action:8} -> {next_status:10} ({note})')

def positive_int(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f'expected int, got {type(value).__name__}')
    if value <= 0:
        raise ValueError(f'expected positive, got {value}')
    return value

def non_empty_str(value):
    if not isinstance(value, str) or not value.strip():
        raise ValueError('expected non-empty string')
    return value.strip()

RULES = {'host': non_empty_str, 'port': positive_int, 'workers': positive_int}

def validate(config):
    clean, errors = {}, []
    for key, value in config.items():
        rule = RULES.get(key)
        if rule is None:
            clean[key] = value
            continue
        try:
            clean[key] = rule(value)
        except ValueError as e:
            errors.append(f'{key}: {e}')
    return clean, errors

