def label(n):
    if n > 0:
        return 'positive'
    if n < 0:
        return 'negative'
    return 'zero'

def segments(nums):
    out, current_label, total = [], None, 0
    count = 0
    for n in nums:
        n_label = label(n)
        if n_label != current_label:
            if current_label is not None:
                out.append((current_label, count, total))
            current_label, total, count = n_label, 0, 0
        total += n
        count += 1
    if current_label is not None:
        out.append((current_label, count, total))
    return out

for segment in segments([1, 3, 5, -2, -4, 0, 7, -1]):
    print(f'{segment[0]:9} count={segment[1]} total={segment[2]}')

REQUIRED = ('name', 'age', 'consent')

def validate(user):
    clean, errors = {}, []

    for field in REQUIRED:
        if field not in user:
            errors.append(f'{field}: required field missing')

    name = user.get('name')
    if name is not None:
        stripped = name.strip() if isinstance(name, str) else ''
        if not stripped:
            errors.append('name: must not be empty')
        else:
            clean['name'] = stripped

    age = user.get('age')
    if age is not None:
        if isinstance(age, bool) or not isinstance(age, int):
            errors.append(f'age: must be an integer, got {type(age).__name__}')
        elif not 18 <= age <= 120:
            errors.append(f'age: must be 18-120, got {age}')
        else:
            clean['age'] = age

    if 'consent' in user:
        consent = user['consent']
        if not isinstance(consent, bool):
            errors.append('consent: must be true or false')
        elif not consent:
            errors.append('consent: must be accepted to continue')
        else:
            clean['consent'] = True

    country = user.get('country')
    state = user.get('state')
    if country == 'IN' and isinstance(state, str) and not state.strip():
        errors.append('state: required when country is IN')
    elif isinstance(state, str):
        clean['state'] = state.strip()

    return clean, errors

