BASE = {'weekday': 200, 'weekend': 300}

def price(age, day='weekday', member=False):
    if age < 0:
        return None, f'invalid age: {age}'
    if day not in BASE:
        return None, f'unknown day type: {day}'

    amount = BASE[day]
    notes = [f'base {amount} for {day}']

    if age < 12:
        amount *= 0.5
        notes.append('child 50% off')
    elif age >= 65:
        amount *= 0.7
        notes.append('senior 30% off')

    if member and age < 12:
        notes.append('member discount not stacked for children')
    elif member:
        amount *= 0.9
        notes.append('member 10% off')

    return round(amount, 2), '; '.join(notes)

for age, day, member in ((8, 'weekday', False), (31, 'weekend', True), (65, 'weekday', True), (8, 'weekend', True)):
    amount, why = price(age, day, member)
    print(f'age={age:>3} {day:8} member={member!s:5} -> {amount:>6} ({why})')

