RECORDS = [('Anjali', 95), ('Rehan', 82), ('Salman', 74), ('Tara', 61), ('Ravi', 39), ('Neha', 140)]

def grade(marks):
    if not isinstance(marks, (int, float)) or isinstance(marks, bool):
        return None, 'invalid marks type'
    if not 0 <= marks <= 100:
        return None, f'marks out of range ({marks})'
    if marks >= 90:
        return 'A', 'pass'
    if marks >= 75:
        return 'B', 'pass'
    if marks >= 60:
        return 'C', 'pass'
    if marks >= 40:
        return 'D', 'pass'
    return 'F', 'fail'

valid, invalid = [], []
for name, marks in RECORDS:
    letter, status = grade(marks)
    if letter is None:
        invalid.append((name, status))
    else:
        valid.append((name, marks, letter, status))

print(f'{"name":<8}{"marks":>6}  grade  status')
for name, marks, letter, status in valid:
    print(f'{name:<8}{marks:>6}  {letter:^5}  {status}')

for name, reason in invalid:
    print(f'{name:<8}  skipped: {reason}')

passes = sum(1 for _, _, _, status in valid if status == 'pass')
print()
print(f'summary: {len(valid)} valid, {len(invalid)} skipped, {passes} passed')
print('average marks:', round(sum(m for _, m, _, _ in valid) / len(valid), 2))

TERMINAL = {'delivered', 'returned', 'cancelled'}

TRANSITIONS = {
    'pay': {'from': {'new', 'payment_failed'}, 'to': 'paid', 'role': 'customer'},
    'fail_payment': {'from': {'new'}, 'to': 'payment_failed', 'role': None},
    'ship': {'from': {'paid'}, 'to': 'shipped', 'role': 'warehouse'},
    'deliver': {'from': {'shipped'}, 'to': 'delivered', 'role': 'courier'},
    'return': {'from': {'delivered'}, 'to': 'returned', 'role': 'customer'},
    'cancel': {'from': {'new', 'paid'}, 'to': 'cancelled', 'role': 'customer'},
}

def step(state, action, context=None):
    context = context or {}
    if state in TERMINAL and action != 'return':
        return state, False, f'{state} is terminal — {action} not allowed'
    rule = TRANSITIONS.get(action)
    if rule is None:
        return state, False, f'unknown action {action!r}'
    if state not in rule['from']:
        allowed = ', '.join(sorted(rule['from']))
        return state, False, f'{action} not allowed from {state} (allowed from: {allowed})'
    required = rule['role']
    if required is not None and context.get('role') != required:
        return state, False, f'{action} requires role {required!r}, got {context.get("role")!r}'
    return rule['to'], True, f'{action}: {state} -> {rule["to"]}'

def run(steps, context=None, dry_run=False):
    state, audit = 'new', []
    for action in steps:
        new_state, ok, note = step(state, action, context)
        audit.append((state, action, new_state if ok else state, ok, note))
        if ok and not dry_run:
            state = new_state
        elif ok and dry_run:
            state = new_state
    return state, audit

print('normal flow:')
final, audit = run(['pay', 'ship', 'deliver'], {'role': 'customer'})
for frm, action, to, ok, note in audit:
    print(f'  {frm:14} --{action:13}--> {to:14} {"ok" if ok else "BLOCKED"}  {note}')
print('  final:', final)

print()
print('illegal + role checks:')
final, audit = run(['ship', 'pay', 'deliver', 'pay', 'cancel'], {'role': 'customer'})
for frm, action, to, ok, note in audit:
    print(f'  {frm:14} --{action:13}--> {to:14} {"ok" if ok else "BLOCKED"}  {note}')
print('  final:', final)

print()
print('summary:', f'{sum(1 for a in audit if a[3])} ok, {sum(1 for a in audit if not a[3])} blocked')
